def hdr(t): return next(csv.reader(open(os.path.join(CSV, t + '.csv'), encoding='utf-8')))
def rows(t): return list(csv.DictReader(open(os.path.join(CSV, t + '.csv'), encoding='utf-8')))
def wr(name, t, data):
    with open(os.path.join(Q, name), 'w', encoding='utf-8', newline='') as f:
        w = csv.DictWriter(f, fieldnames=hdr(t), lineterminator='\n'); w.writeheader()
        for r in data: w.writerow({k: r.get(k, '') for k in hdr(t)})

