P = []
def ps(i, e, s, q, note, qt='原文'):
    P.append(dict(id=i, event_id=e, source_id=s, quote_original=q, modern_note=note, quote_type=qt))
ps('Q746', 'E402', 'Z181', '秋，宋大水。公使吊焉，曰：『天作淫雨，害于粢盛，若之何不吊？』對曰：『孤實不敬，天降之災，又以爲君憂，拜命之辱。』臧文仲曰：『宋其興乎。禹、湯罪己，其興也悖焉；桀、紂罪人，其亡也忽焉。且列國有凶稱孤，禮也。言懼而名禮，其庶乎。』既而聞之曰公子禦說之辭也。臧孫達曰：『是宜爲君，有恤民之心。』',
   '《左传·庄公十一年》：秋，宋国大水。（鲁庄）公派人去慰问，说：「上天降下久雨，伤害了祭祀的谷物，怎能不来慰问？」（宋方）回答说：「是我不敬，上天降灾，又让贵君忧虑，拜谢您的慰问。」臧文仲说：「宋国大概要兴盛了吧。禹、汤归罪于自己，他们的兴起很迅速；桀、纣归罪于别人，他们的灭亡很突然。况且列国有凶灾时自称「孤」，是合于礼的。言辞有戒惧而称谓合礼，大概差不多了。」不久听说这是公子御说的话。臧孙达说：「这个人适合做国君，有体恤百姓之心。」〔底本此段引号作『』，照录。〕' + DB)
ps('Q747', 'E403', 'Z034', '秋，八月，辛丑，公薨。……九月，夫人姜氏孫于邾。公子慶父出奔莒。',
   '【经之书法·讳弑】《春秋·闵公二年》经：秋八月辛丑，（闵）公薨。九月，夫人姜氏出奔到邾，公子庆父出奔到莒。〔经书「薨」不书「弑」，「孫」为出奔之讳辞；其事之详见传（`Q748`、`Q749`）。〕' + DB)
ps('Q748', 'E403', 'Z034', '初，公傅奪卜齮田，公不禁。秋八月辛丑，共仲使卜齮賊公于武闈。成季以僖公適邾。共仲奔莒，乃入，立之。以賂求共仲于莒，莒人歸之。及密，使公子魚請。不許，哭而往。共仲曰：「奚斯之聲也。」乃縊。',
   '《左传·闵公二年》：当初，闵公的师傅夺取了卜齮的田地，闵公不加禁止。秋八月辛丑，共仲（庆父）指使卜齮在武闱刺杀闵公。成季（季友）带着僖公逃到邾国。共仲逃往莒国，（成季）于是回国，立僖公为君。用财货向莒国求取共仲，莒人把他送回。到了密地，（共仲）派公子鱼去求情，不被允许，（公子鱼）哭着回去。共仲说：「这是奚斯（公子鱼）的哭声。」于是自缢。' + DB)
ps('Q749', 'E403', 'Z034', '閔公，哀姜之娣叔姜之子也，故齊人立之。共仲通於哀姜，哀姜欲立之。閔公之死也，哀姜與知之，故孫于邾。齊人取而殺之于夷，以其尸歸，僖公請而葬之。',
   '《左传·闵公二年》：闵公是哀姜之妹叔姜的儿子，所以齐人立他为君。共仲与哀姜私通，哀姜想立共仲为君。闵公之死，哀姜参与知情，所以出奔到邾国。齐人把她取回并在夷地杀了她，带着她的尸体回去，僖公请求（归还）而安葬了她。〔「通於」「與知之」系传文之叙，其归罪属文本立场；「齊人取而殺之于夷」为预叙，其事经系于僖公元年，见 `E404`。〕' + DB)
ps('Q750', 'E404', 'Z035', '秋，七月，戊辰。夫人姜氏薨于夷，齊人以歸。……十有二月，丁已，夫人氏之喪至自齊。',
   '【经之书法·讳杀】《春秋·僖公元年》经：秋七月戊辰，夫人姜氏死于夷地，齐人把（她的尸体）带回去。十二月丁巳，夫人的灵柩从齐国运回。〔经书「薨」，传书齐人杀之（`Q749`、`Q751`）。底本「丁已」之「已」照录，当为「巳」之形讹，纸本未核。〕' + DB)
ps('Q751', 'E404', 'Z035', '夫人氏之喪至自齊，君子以齊人殺哀姜也，為已甚矣。女子從人者也。',
   '《左传·僖公元年》：夫人的灵柩从齐国运回。君子认为齐人杀哀姜，做得太过分了。女子是从属于（夫家）人的。〔「為已甚矣」是君子之评，属文本立场。〕' + DB)
ps('Q752', 'E405', 'Z068', '夏，大旱，公欲焚巫、尫。臧文仲曰：「非旱備也。脩城郭，貶食省用，務穡勸分，此其務也，巫、尫何為？天欲殺之，則如勿生。若能為旱，焚之滋甚。」公從之。是歲也，饑而不害。',
   '《左传·僖公二十一年》：夏，大旱，（鲁僖）公想要焚烧巫者和尫者（求雨）。臧文仲说：「这不是防备旱灾的办法。修城郭，减膳食、省用度，致力农事、劝人分施，这才是该做的。巫、尫能做什么？上天要杀他们，就不如不生他们；如果他们能造成旱灾，烧了他们旱灾更甚。」公听从了他。这一年虽有饥荒而没有造成伤害。' + DB)
ps('Q753', 'E406', 'Z134', '八月，丁卯，大事于大廟，躋僖公。',
   '《春秋·文公二年》经：八月丁卯，在太庙举行大祭，把僖公（的神主）升到（闵公）之上。' + DB)
ps('Q754', 'E406', 'Z134', '秋八月，丁卯，大事于大廟，躋僖公，逆祀也。於是夏父弗忌為宗伯，尊僖公，且明見曰：「吾見新鬼大，故鬼小，先大後小，順也。躋聖賢，明也。明順，禮也。」君子以為失禮。',
   '《左传·文公二年》：秋八月丁卯，在太庙大祭，升僖公之位，这是颠倒祭祀次序。当时夏父弗忌任宗伯，尊崇僖公，并且宣称他所见：「我看见新鬼大，旧鬼小。先大后小，是顺序；升圣贤，是明智。明智而顺，就是礼。」君子认为这是失礼。〔僖公为闵公之庶兄而继闵公为君，跻之于闵公之上，传谓之「逆祀」。底本此页引号以维基字词转换标记 `-{「}-` 包之，比字时去其标记。〕' + DB)
ps('Q755', 'E406', 'Z134', '仲尼曰：「臧文仲其不仁者三，不知者三。下展禽、廢六關、妾織蒲，三不仁也。作虛器、縱逆祀、祀爰居，三不知也。」',
   '【评断之辞·非编年记事】《左传·文公二年》：仲尼说：「臧文仲不仁之事有三，不智之事有三。使展禽（柳下惠）居于下位、废除六处关卡、让妾织蒲席（与民争利），是三不仁；造无用之器、纵容逆祀、祭祀爰居（海鸟），是三不知。」〔此为《左传》评语账评-2（`docs/kaoding_kongzi.md` §1），r49 时「无骨架可挂」未收；本件以 `E406`（跻僖公逆祀）为其骨架，其「縱逆祀」即指本事。六事之释从通行注说，杜注本件未核。〕' + DB, '评论')
ps('Q756', 'E406', 'G018', '夏父弗忌為宗，蒸將躋僖公。宗有司曰：「非昭穆也。」曰：「我為宗伯，明者為昭，其次為穆，何常之有！」有司曰：「夫宗廟之有昭穆也，以次世之長幼，而等冑之親疏也。夫祀，昭孝也。各致齊敬於其皇祖，昭孝之至也。故工史書世，宗祝書昭穆，猶恐其踰也。今將先明而後祖，自玄王以及主癸莫若湯，自稷以及王季莫若文、武，商、周之蒸也，未嘗躋湯與文、武，為不踰也。魯未若商、周而改其常，無乃不可乎？」弗聽，遂躋之。',
   '《国语·鲁语上》「夏父弗忌改昭穆之常」：夏父弗忌做宗伯，蒸祭时要把僖公升位。宗庙的有司说：「这不合昭穆之序。」（弗忌）说：「我是宗伯，明德者为昭，其次为穆，有什么常规！」有司说：「宗庙设昭穆，是按世代长幼排序、区分后嗣亲疏。祭祀是彰明孝道……如今要先尊明德而后排祖先……鲁国比不上商、周却改变常规，恐怕不行吧？」（弗忌）不听，终于升了僖公。〔与《左传·文公二年》同事（`Q754`），二书措辞有异（传书「明見」，此书与有司之辩），所指行动一致。〕' + DBG)
ps('Q758', 'E407', 'Z059', '秋，季孫行父如晉。',
   '《春秋·文公六年》经：秋，季孙行父（季文子）到晋国去。' + DB)
ps('Q759', 'E407', 'Z059', '秋，季文子將聘於晉，使求遭喪之禮以行。其人曰：『將焉用之？』文子曰：「備豫不虞，古之善教也。求而無之，實難。過求何害？」',
   '《左传·文公六年》：秋，季文子将去晋国聘问，让人求取遭遇丧事时的礼仪然后才出发。随从的人说：「哪里用得着这个？」文子说：「预备意外，是古代的好教训。临时去求而没有，那就难办了。多求一点有什么害处？」〔同年八月晋襄公卒（经传），季文子之备乃有所用。底本此处外层『』、内层「」以维基字词转换标记包之，去标记后照录。〕' + DB)
ps('Q760', 'E408', 'Z182', '莒紀公子生大子僕，又生季佗，愛季佗而黜僕，且多行禮於國，僕因國人以弒紀公，以其寶玉來奔，納諸宣公，公命與之邑，曰，今日必授，季文子使司寇出諸竟，曰，今日必達，公問其故，季文子使大史克對曰，先大夫臧文仲，教行父事君之禮，行父奉以周旋，弗敢失隊，曰，見有禮於其君者事之，如孝子之養父母也，見無禮於其君者誅之，如鷹鸇之逐鳥雀也，……今行父雖未獲一吉人，去一凶矣，於舜之功，二十之一也，庶幾免於戾乎，',
   '《左传·文公十八年》：莒纪公生太子仆，又生季佗，宠爱季佗而废黜仆，并且在国内多行无礼之事。仆依靠国人杀了纪公，带着他的宝玉逃来鲁国，献给宣公。宣公命令给他城邑，说：「今天一定要给。」季文子让司寇把他驱逐出境，说：「今天一定要送到。」宣公问其缘故，季文子让太史克回答说：「先大夫臧文仲教导行父事奉国君的礼节，行父奉行周旋，不敢失坠。（臧文仲）说：见到对其国君有礼的人就事奉他，如孝子奉养父母；见到对其国君无礼的人就诛除他，如鹰鹯追逐鸟雀。……如今行父虽然没有举得一个吉人，却去掉了一个凶人，对于舜的功业来说，算是二十分之一，或许可以免于罪过了吧。」〔中略之文为周公之誓命、八恺八元与四凶之喻。底本此页以「，」通断，照录。〕' + DB)
ps('Q761', 'E408', 'G018', '莒太子僕弒紀公，以其寶來奔。宣公使僕人以書命季文子曰：「夫莒太子不憚以吾故殺其君，而以其寶來，其愛我甚矣。為我予之邑。今日必授，無逆命矣。」里革遇之而更其書曰：「夫莒太子殺其君而竊其寶來，不識窮固又求自邇，為我流之於夷。今日必通，無逆命矣。」',
   '《国语·鲁语上》「里革更書逐莒太子僕」：莒太子仆杀了纪公，带着他的宝物逃来。宣公派僕人带着文书命令季文子说：「莒太子不惜为我而杀他的国君，又带着宝物来，他很爱我。替我给他城邑，今天一定要给，不要违命。」里革遇见僕人，就改了文书说：「莒太子杀其君而窃其宝来，不知困穷而又求自近于我，替我把他流放到夷地去。今天一定要送到，不要违命。」〔与《左传·文公十八年》（`Q760`）同事而所叙之行与人俱异：传书季文子使司寇出之、使大史克对；此书里革更改君书。二书各为一书，并陈不裁。〕' + DBG)
ps('Q762', 'E409', 'Z183', '元年春王正月，公即位。公子遂如齊逆女。……三月，遂以夫人婦姜至自齊。',
   '《春秋·宣公元年》经：元年春王正月，（宣）公即位。公子遂到齐国迎接夫人。三月，公子遂带着夫人妇姜从齐国回来。〔「夫人婦姜」即穆姜，其同人之推见 `P_MUJIANG.notes`。〕' + DB)
ps('Q763', 'E409', 'Z183', '元年春王正月，公子遂如齊逆女，尊君命也。……三月，遂以夫人婦姜至自齊，尊夫人也。',
   '《左传·宣公元年》：元年春王正月，公子遂到齐国迎接夫人，（经称「公子遂」）是尊重国君之命。三月，公子遂带着夫人妇姜从齐国回来，（经去其「公子」之称）是尊重夫人。' + DB)
ps('Q764', 'E410', 'Z184', '夏。季孫行父如宋致女。',
   '《春秋·成公九年》经：夏，季孙行父到宋国致女（送嫁后问候）。' + DB)
ps('Q765', 'E410', 'Z184', '夏‧季文子如宋致女。復命。公享之。賦韓奕之五章。穆姜出于房。再拜曰。大夫勤辱。不忘先君。以及嗣君。施及未亡人。先君猶有望也。敢拜大夫之重勤。又賦綠衣之卒章而入。',
   '《左传·成公九年》：夏，季文子到宋国致女，回来复命，（成）公设享礼招待他。（季文子）赋《韩奕》第五章。穆姜从房中出来，拜了两拜，说：「大夫辛劳，不忘先君，以及嗣君，并且惠及我这未亡人，先君也会有所期望的。谨拜谢大夫的加倍辛劳。」又赋《绿衣》的最后一章，然后进去。〔底本「夏‧」之「‧」照录。〕' + DB)
ps('Q766', 'E411', 'Z089', '宣伯通於穆姜。欲去季孟。而取其室。將行。穆姜送公。而使逐二子。公以晉難告。曰。請反而聽命。姜怒。公子偃。公子鉏。趨過指之曰。女不可。是皆君也。公待於壞隤。申宮儆備。設守而後行。是以後。使孟獻子守于公宮。',
   '《左传·成公十六年》：宣伯（叔孙侨如）与穆姜私通，想去掉季孙（季文子）、孟孙（孟献子）而夺取他们的家产。（成公）将要出发，穆姜送公，让他驱逐这两个人。公以晋国之难为由推托，说：「请等我回来再听从您的命令。」穆姜发怒，公子偃、公子鉏快步走过，她指着他们说：「你若不答应，这两个人都可以做国君！」公在坏隤等待，加强宫中戒备，设置守卫之后才出发，因此迟到了。派孟献子留守公宫。〔「通於」系传文之叙，其归罪属文本立场。〕' + DB)
ps('Q767', 'E411', 'Z089', '七月。公會尹武公。及諸侯伐鄭。將行。姜又命公如初。公又申守而行。',
   '《左传·成公十六年》：七月，（成）公会同尹武公及诸侯攻打郑国。将要出发时，穆姜又像上次那样命令公（逐二子），公又加强守备之后才出发。' + DB)
ps('Q768', 'E412', 'Z089', '九月。晉人執季孫行父。舍之于苕丘。冬。十月。乙亥。叔孫僑如出奔齊。',
   '《春秋·成公十六年》经：九月，晋人拘捕季孙行父，把他安置在苕丘。冬十月乙亥，叔孙侨如出奔到齐国。' + DB)
ps('Q769', 'E412', 'Z089', '宣伯使告郤犨曰。魯之有季孟。猶晉之有欒范也。政令於是乎成。今其謀曰。晉政多門。不可從也。寧事齊楚。有亡而已。蔑從晉矣。若欲得志於魯。請止行父而殺之。我斃蔑也。而事晉。蔑有貳矣。',
   '《左传·成公十六年》：宣伯派人告诉郤犨说：「鲁国有季孙、孟孙，就像晋国有栾氏、范氏，政令由他们制定。现在他们谋划说：『晋国政出多门，不可听从。宁可事奉齐、楚，即使灭亡也罢了，不再听从晋国了。』如果想在鲁国得志，请扣留行父而杀了他，我杀掉蔑（孟献子），而事奉晋国，就不会有二心了。」〔此为宣伯之谮辞，其所言季孟之谋属其一面之言。〕' + DB)
ps('Q770', 'E412', 'Z089', '九月。晉人執季文子于苕丘。公還。待于鄆。使子叔聲伯請季孫于晉。郤犨曰。苟去仲孫蔑而止季孫行父。吾與子國。親於公室。……范文子謂欒武子曰。季孫於魯。相二君矣。妾不衣帛。馬不食粟。可不謂忠乎。信讒慝而棄忠良。若諸侯何。……乃許魯平。赦季孫。',
   '《左传·成公十六年》：九月，晋人在苕丘拘捕了季文子。（成）公返回，在郓地等待，派子叔声伯到晋国请求释放季孙。郤犨说：「如果去掉仲孙蔑而扣留季孙行父，我把鲁国的政权交给您，（待您）比公室还亲。」……范文子对栾武子说：「季孙在鲁国，辅佐了两位国君，他的妾不穿丝帛，马不吃粮食，能不说是忠吗？听信谗言而抛弃忠良，对诸侯怎么交代？」……于是允许与鲁讲和，赦免了季孙。〔中略之文为声伯辞郤犨之邑、范文子论子叔婴齐之言。〕' + DB)
ps('Q771', 'E412', 'Z089', '冬。十月。出叔孫僑如而盟之。僑如奔齊。十二月。季孫及郤犨盟于扈。歸刺公子偃。召叔孫豹于齊而立之。',
   '《左传·成公十六年》：冬十月，（鲁人）驱逐叔孙侨如并为此盟誓，侨如逃往齐国。十二月，季孙与郤犨在扈地结盟，回国后杀了公子偃，从齐国召回叔孙豹而立他（为叔孙氏之后）。' + DB)
ps('Q772', 'E412', 'G018', '子叔聲伯如晉謝季文子，郤犫欲予之邑，弗受也。',
   '《国语·鲁语上》「子叔聲伯辭邑」：子叔声伯到晋国为季文子之事致谢（请释），郤犨想给他城邑，他不接受。〔本章其下为声伯答鲍国之论，本件不录。《国语》作「郤犫」，《左传》作「郤犨」，名物用字之异，照录。〕' + DBG)
ps('Q773', 'E413', 'Z090', '夏．叔孫豹如晉．',
   '《春秋·襄公四年》经：夏，叔孙豹到晋国去。' + DB)
ps('Q774', 'E413', 'Z090', '穆叔如晉．報知武子之聘也．晉侯享之．金奏肆夏之三．不拜．工歌文王之三．又不拜．歌鹿鳴之三．三拜．韓獻子使行人子員問之．曰．子以君命辱於敝邑．先君之禮．藉之以樂．以辱吾子．吾子舍其大而重．拜其細．敢問何禮也．對曰．三夏．天子所以享元侯也．使臣弗敢與聞．文王．兩君相見之樂也．臣不敢及．鹿鳴．君所以嘉寡君也．敢不拜嘉．四牡．君所以勞使臣也．敢不重拜．皇皇者華．君教使臣曰．必諮於周．臣聞之．訪問於善為咨．咨親為詢．咨禮為度．咨事為諏．咨難為謀．臣獲五善．敢不重拜．',
   '《左传·襄公四年》：穆叔到晋国，回报知武子（荀罃）的聘问。晋侯设享礼招待他，钟镈奏《肆夏》三曲，他不拜；乐工歌《文王》三曲，又不拜；歌《鹿鸣》三曲，三次下拜。韩献子派行人子员问他：「您奉君命来到敝邑，我们以先君之礼、用音乐来招待您。您舍弃重大的而对细小的一再下拜，请问这是什么礼？」回答说：「《三夏》是天子用来招待元侯的，使臣不敢与闻。《文王》是两国国君相见的音乐，使臣不敢涉及。《鹿鸣》是贵君用来嘉奖寡君的，敢不拜谢嘉奖？《四牡》是贵君用来慰劳使臣的，敢不再拜？《皇皇者华》中贵君教导使臣说：必须向忠信之人咨询。臣听说：向善人访问为咨，咨问亲戚为询，咨问礼仪为度，咨问政事为诹，咨问患难为谋。臣得到这五善，敢不再拜？」' + DB)
ps('Q775', 'E413', 'G013', '叔孫穆子聘於晉，晉悼公饗之，樂及《鹿鳴》之三，而後拜樂三。晉侯使行人問焉，曰：「子以君命鎮撫弊邑，不腆先君之禮，以辱從者，不腆之樂以節之。吾子舍其大而加禮於其細，敢問何禮也？」',
   '《国语·鲁语下》「叔孫穆子聘於晉」：叔孙穆子到晋国聘问，晋悼公以飨礼招待他，奏乐到《鹿鸣》等三曲，然后三次拜谢。晋侯派行人问他：「您奉君命来安抚敝邑，我们以先君之薄礼款待您，用菲薄的音乐来节制礼仪。您舍弃大的而对小的加礼，请问这是什么礼？」〔其下穆子之对与《左传·襄公四年》（`Q774`）大同，措辞有异（如「六德」与「五善」），本件不全录。《国语》明书晋侯为悼公。〕' + DBG)
ps('Q776', 'E414', 'Z185', '十有二月．公至自救陳．辛未．季孫行父卒．',
   '《春秋·襄公五年》经：十二月，（襄）公从救陈之役回国。辛未，季孙行父去世。' + DB)
ps('Q777', 'E414', 'Z185', '季文子卒．大夫入斂．公在位．宰庀家器為葬備．無衣帛之妾．無食粟之馬．無藏金玉．無重器備．君子是以知季文子之忠於公室也．相三君矣．而無私積．可不謂忠乎．',
   '《左传·襄公五年》：季文子去世，大夫入殓，（襄）公亲临就位。家宰收拾家中器物作为葬具，（家中）没有穿丝帛的妾，没有吃粮食的马，没有收藏的金玉，没有贵重成套的器物。君子因此知道季文子对公室的忠诚：辅佐了三位国君，却没有私人积蓄，能不说是忠吗？' + DB)
ps('Q778', 'E414', 'G018', '季文子相宣、成，無衣帛之妾，無食粟之馬。仲孫它諫曰：「子為魯上卿，相二君矣，妾不衣帛，馬不食粟，人其以子為愛，且不華國乎！」文子曰：「吾亦願之。然吾觀國人，其父兄之食麤而衣惡者猶多矣，吾是以不敢。人之父兄食麤衣惡，而我美妾與馬，無乃非相人者乎！且吾聞以德榮為國華，不聞以妾與馬。」',
   '《国语·鲁语上》「季文子論妾馬」：季文子辅佐宣公、成公，没有穿丝帛的妾，没有吃粮食的马。仲孙它劝谏说：「您是鲁国的上卿，辅佐两位国君了，妾不穿丝帛，马不吃粮食，别人恐怕会以为您吝啬，而且也不能为国增光吧！」文子说：「我也愿意那样。可是我看国人之中，父兄吃粗粮穿破衣的还很多，所以我不敢。别人的父兄吃粗粮穿破衣，而我却让妾和马过得好，这恐怕不是辅佐国君的人吧！况且我只听说以德行荣耀为国增光，没听说以妾和马。」〔本章不系年；依 conventions §7 v1.16 就近挂靠其卒年之目 `E414`（传书其「無衣帛之妾．無食粟之馬」）。〕' + DBG)
ps('Q779', 'E415', 'Z141', '冬．十月．衛侯使孫林父來聘．壬戌．及孫林父盟．',
   '《春秋·襄公七年》经：冬十月，卫侯派孙林父来鲁国聘问。壬戌，（鲁）与孙林父结盟。' + DB)
ps('Q780', 'E415', 'Z141', '衛孫文子來聘．且拜武子之言．而尋孫桓子之盟．公登亦登．叔孫穆子相．趨進曰．諸侯之會．寡君未嘗後衛君．今吾子不後寡君．寡君未知所過．吾子其少安．孫子無辭．亦無悛容．穆叔曰．孫子必亡．為臣而君．過而不悛．亡之本也．詩曰．退食自公．委蛇委蛇．謂從者也．衡而委蛇必折．',
   '《左传·襄公七年》：卫国孙文子来鲁聘问，并拜谢季武子的话，重温孙桓子时的盟约。（襄）公登阶，他也同时登阶。叔孙穆子为相礼，快步上前说：「诸侯会见时，寡君从未落在卫君之后。如今您不落在寡君之后，寡君不知道自己有什么过错。请您稍稍放慢。」孙子没有答话，也没有改悔的样子。穆叔说：「孙子必定败亡。作为臣子而与国君并行，有了过错而不改，这是败亡的根本。《诗》说：『退朝回家吃饭，从容自得』，说的是顺从的人。专横而又自得，必定折断。」' + DB)
ps('Q781', 'E416', 'Z142', '五月．辛酉．夫人姜氏薨．……秋．八月．癸未．葬我小君穆姜．',
   '《春秋·襄公九年》经：五月辛酉，夫人姜氏去世。秋八月癸未，安葬我国君夫人穆姜。' + DB)
ps('Q782', 'E416', 'Z142', '穆姜薨於東宮．始往而筮之．遇艮之八．史曰．是謂艮之隨．隨其出也．君必速出．姜曰．亡．是於周易．曰．隨元亨利貞．咎．元．體之長也．亨．嘉之會也．利．義之和也．貞．事之幹也．體仁足以長人．嘉德足以合禮．利物足以和義．貞固足以幹事．然故不可誣也．是以雖隨無咎．今我婦人而與於亂．固在下位．而有不仁．不可謂元．不靖國家．不可謂亨．作而害身．不可謂利．棄位而姣．不可謂貞．有四德者．隨而無咎．我皆無之．豈隨也哉．我則取惡．能無咎乎．必死於此．弗得出矣．',
   '《左传·襄公九年》：穆姜死于东宫。当初她刚迁往东宫时占筮，遇到《艮》卦变为八。史官说：「这叫做《艮》之《随》。随，是出去的意思，您一定能很快出去。」穆姜说：「不会。在《周易》里说：《随》，元亨利贞，无咎。元，是身体的首长；亨，是嘉美的聚会；利，是道义的和谐；贞，是事情的主干。体现仁足以做人之长，美德足以合乎礼，利物足以和合道义，坚贞足以办好事情。正因如此，所以不可欺诬，因此虽遇《随》卦也无咎。如今我作为妇人而参与了动乱，本来就处于低下的地位而又不仁，不能说是元；不能安定国家，不能说是亨；作乱而害了自身，不能说是利；不守其位而修饰容貌，不能说是贞。有这四德的人，遇到《随》才无咎；我都没有，难道能合于《随》吗？我自取邪恶，能没有灾咎吗？必定死在这里，不能出去了。」〔「與於亂」「棄位而姣」为穆姜自述之辞，传所载之言。【底本之字】「是以雖隨無咎」之「無」，底本作私用区字符 U+F6E3（不可读）；同页襄公二十七年「棠無咎」之「無」三处亦作此符而同叙上文作正字（r62-P `Q715`、`Q716` 已推），据此推其为「無」，录作「無」——推非底本之字，纸本未核。又卦辞「隨元亨利貞．咎」底本无「無」字（《周易》随卦辞通行作「元亨利貞，無咎」），照底本录，不补，纸本未核。〕' + DB)
ps('Q783', 'E417', 'Z081', '二十有四年春．叔孫豹如晉．',
   '《春秋·襄公二十四年》经：二十四年春，叔孙豹到晋国去。' + DB)
ps('Q784', 'E417', 'Z081', '二十四年春．穆叔如晉．范宣子逆之問焉．曰．古人有言曰．死而不朽．何謂也．穆叔未對．宣子曰．昔匄之祖．自虞以上為陶唐氏．在夏為御龍氏．在商為豕韋氏．在周為唐杜氏．晉主夏盟為范氏．其是之謂乎．穆叔曰．以豹所聞．此之謂世祿．非不朽也．魯有先大夫曰臧文仲．既沒．其言立．其是之謂乎．豹聞之．大上有立德．其次有立功．其次有立言．雖久不廢．此之謂不朽．若夫保姓受氏．以守宗祊．世不絕祀．無國無之．祿之大者．不可謂不朽．',
   '《左传·襄公二十四年》：二十四年春，穆叔到晋国，范宣子迎接他，问道：「古人有句话说『死而不朽』，说的是什么？」穆叔没有回答。宣子说：「从前匄的祖先，自虞舜以上是陶唐氏，在夏为御龙氏，在商为豕韦氏，在周为唐杜氏，晋主持中原盟会时为范氏，大概说的就是这个吧？」穆叔说：「据豹所听说的，这叫做世禄，不是不朽。鲁国有位先大夫叫臧文仲，死了以后，他的话仍立于世，说的大概是这个吧。豹听说：最上是树立德行，其次是建立功业，其次是树立言论，虽然久远而不废弃，这叫做不朽。至于保存姓氏、守护宗庙、世代不断祭祀，没有哪个国家没有，这只是禄位中的大者，不能说是不朽。」' + DB)
ps('Q785', 'E417', 'G009', '魯襄公使叔孫穆子來聘，范宣子問焉，曰：「人有言曰：『死而不朽』，何謂也？」穆子未對。宣子曰：「昔匄之祖，自虞以上為陶唐氏，在夏為御龍氏，在商為豕韋氏，在周為唐、杜氏。周卑，晉繼之，為范氏，其此之謂也？」對曰：「以豹所聞，此之謂世祿，非不朽也。魯先大夫臧文仲，其身歿矣，其言立於後世，此之謂死而不朽。」',
   '《国语·晋语八》「叔孫穆子論死而不朽」：鲁襄公派叔孙穆子来晋聘问，范宣子问他：「人们说『死而不朽』，指的是什么？」穆子没有回答。宣子说：「从前匄的祖先……周室衰微，晋继之为霸，（我族）为范氏，说的大概就是这个吧？」（穆子）回答说：「据豹所闻，这叫世禄，不是不朽。鲁国先大夫臧文仲，身虽死了，他的话却立于后世，这才叫死而不朽。」〔与《左传·襄公二十四年》（`Q784`）同事；《国语》此章止于臧文仲之例，无「立德、立功、立言」之三分，措辞之异，并陈。〕' + DBG)
ps('Q786', 'E418', 'Z146', '元年春．王正月．公即位．叔孫豹會晉趙武．楚公子圍．齊國弱．宋向戌．衛齊惡．陳公子招．蔡公孫歸生．鄭罕虎．許人．曹人．于虢．',
   '《春秋·昭公元年》经：元年春王正月，（昭）公即位。叔孙豹在虢地会见晋国赵武、楚国公子围、齐国国弱、宋国向戌、卫国齐恶、陈国公子招、蔡国公孙归生、郑国罕虎以及许国人、曹国人。' + DB)
ps('Q787', 'E418', 'Z146', '三月．甲辰．盟．楚公子圍設服離衛．叔孫穆子曰．楚公子美矣．君哉．',
   '《左传·昭公元年》：三月甲辰，结盟。楚国公子围陈设国君的服饰、两人执戈护卫。叔孙穆子说：「楚公子真漂亮啊，像个国君了！」〔其下诸国大夫之评，本件不录。〕' + DB)
ps('Q788', 'E418', 'Z146', '季武子伐莒．取鄆．莒人告於會．楚告於晉曰．尋盟未退．而魯伐莒．瀆齊盟．請戮其使．樂桓子相趙文子．欲求貨於叔孫．而為之請．使請帶焉弗與．梁其脛曰．貨以藩身．子何愛焉．叔孫曰．諸侯之會．衛社稷也．我以貨免．魯必受師．是禍之也．何衛之為．……然鮒也賄．弗與不已．召使者裂裳帛而與之．曰帶其褊矣．趙孟聞之曰．臨患不忘國．忠也．思難不越官．信也．圖國忘死．貞也．謀主三者．義也．有是四者．又可戮乎．……魯叔孫豹可謂能矣．請免之以靖能者．……固請諸楚．楚人許之．乃免叔孫．',
   '《左传·昭公元年》：季武子攻打莒国，占取郓地。莒人向盟会控告。楚国告诉晋国说：「重温盟约还未结束，而鲁国攻打莒国，亵渎了盟约，请杀掉鲁国的使者。」乐桓子为赵文子相礼，想向叔孙求取财货，而替他请求，派人向他要带子，叔孙不给。梁其踁说：「财货是用来保护自身的，您吝惜什么？」叔孙说：「诸侯的盟会，是为了保卫国家。我用财货免祸，鲁国必定遭受攻伐，这是给鲁国招祸，还保卫什么？……不过乐王鲋贪财，不给他是不会罢休的。」召来使者，撕下一片裳帛给他，说：「带子恐怕太窄了。」赵孟听说后说：「面临祸患不忘国家，是忠；想到危难而不失职守，是信；为国家打算而忘记死亡，是贞；谋划以这三者为主，是义。有这四种品德，又怎么可以杀呢？」……（赵孟向楚人说）「鲁国的叔孙豹可以说是贤能的了，请赦免他来安定贤能之人。」……坚持向楚国请求，楚人答应了，于是赦免了叔孙。〔中略之文为叔孙怨季孙之言、赵孟论疆场之邑之长篇。〕' + DB)
ps('Q789', 'E418', 'G013', '虢之會，諸侯之大夫尋盟未退。季武子伐莒取鄆，莒人告于會，楚人將以叔孫穆子為戮。晉樂王鮒求貨於穆子，曰：「吾為子請於楚。」穆子不予。',
   '《国语·鲁语下》「叔孫穆子不以貨私免」：虢之会，诸侯的大夫重温盟约还未散去。季武子攻打莒国，取了郓地，莒人向盟会控告，楚人要杀叔孙穆子。晋国乐王鲋向穆子索取财货，说：「我替您向楚国求情。」穆子不给。〔其下穆子答梁其踁之言与《左传》（`Q788`）措辞有异，本件不全录；《国语》书「楚人乃赦之」，不言赵孟之请。〕' + DBG)
ps('Q790', 'E419', 'Z186', '冬．十有二月．乙卯．叔孫豹卒．',
   '《春秋·昭公四年》经：冬十二月乙卯，叔孙豹去世。' + DB)
ps('Q791', 'E419', 'Z186', '初．穆子去叔孫氏．及庚宗．遇婦人．使私為食而宿焉．……既立．所宿庚宗之婦人．獻以雉．問其姓．對曰．余子長矣．能奉雉而從我矣．召而見之．則所夢也．未問其名．號之曰牛．曰唯．皆召其徒．使視之．遂使為豎．有寵．長使為政．……田於丘蕕．遂遇疾焉．豎牛欲亂其室而有之．……疾急．命召仲．牛許而不召．……豎牛曰．夫子疾病．不欲見人．使寘饋于個而退．牛弗進．則置虛命徹．',
   '《左传·昭公四年》：当初，穆子离开叔孙氏（出奔），到了庚宗，遇到一个妇人，让她私下给他做饭并住宿在她家。……（穆子回鲁）立为卿后，在庚宗住宿过的那个妇人献上野鸡。（穆子）问她的儿子（「姓」，杜注训「子」，纸本未核），她回答说：「我的儿子已经长大了，能捧着野鸡跟随我来了。」召来一看，就是梦中所见之人。没问他的名字，就叫他「牛」，他应声说「唯」。（穆子）召集他的随从都来看他，于是让他做了小臣，受到宠爱，长大后让他管理家政。……（穆子）在丘莸打猎，于是得了病。竖牛想搅乱叔孙家而占有它。……（穆子）病重，命令召仲壬回来，竖牛答应了却不去召。……竖牛说：「夫子病重，不想见人。」让人把饭食放在厢房里就退出。竖牛不送进去，就把空的器皿放回，命人撤去。〔中略之文为穆子适齐娶国氏、梦天压己而牛助之、竖牛杀孟丙逐仲壬、杜洩见之诸节。〕' + DB)
ps('Q792', 'E419', 'Z186', '十二月．癸丑．叔孫不食．乙卯．卒．牛立昭子而相之．',
   '《左传·昭公四年》：十二月癸丑，叔孙（豹）得不到食物。乙卯，去世。竖牛立昭子（叔孙婼）而辅佐他。' + DB)
ps('Q793', 'E420', 'Z187', '仲至自齊．季孫欲立之．南遺曰．叔孫氏厚．則季氏薄．彼實家亂．子勿與知．不亦可乎．南遺使國人助豎牛．以攻諸大庫之庭．司宮射之．中目而死．豎牛取東鄙三十邑．以與南遺．昭子即位．朝其家眾曰．豎牛禍叔孫氏．使亂大從．殺適立庶．又披其邑．將以赦罪．罪莫大焉．必速殺之．豎牛懼．奔齊．孟、仲之子．殺諸塞關之外．投其首於寧風之棘上．',
   '《左传·昭公五年》：仲壬从齐国回来，季孙想立他。南遗说：「叔孙氏势力强，季氏就弱。他们家里作乱，您不参与，不也可以吗？」南遗让国人帮助竖牛，在大库的庭院攻打仲壬，司宫射他，射中眼睛而死。竖牛取了东部边境三十个城邑送给南遗。昭子即位，召集家众朝见，说：「竖牛祸害叔孙氏，使大乱从此而起，杀嫡立庶，又分散我家的城邑，想以此求得赦罪，没有比这更大的罪了，一定要赶快杀掉他。」竖牛害怕，逃往齐国。孟丙、仲壬的儿子在塞关之外杀了他，把他的头扔在宁风的荆棘上。' + DB)
ps('Q794', 'E420', 'Z187', '仲尼曰．叔孫昭子之不勞．不可能也．周任有言曰．為政者不賞私勞．不罰私怨．詩云．有覺德行．四國順之．',
   '【评断之辞·非编年记事】《左传·昭公五年》：仲尼说：「叔孙昭子不酬谢（竖牛立己之）私劳，这是难能的。周任有句话说：执政的人不赏私人的功劳，不罚私人的怨恨。《诗》说：有正直的德行，四方之国都顺从他。」〔此为《左传》评语账评-9（`docs/kaoding_kongzi.md` §1），r49 时未收；本件以 `E420` 为其骨架。〕' + DB, '评论')
ps('Q795', 'E420', 'Z187', '初．穆子之生也．莊叔以周易筮之．遇明夷之謙．以示卜楚丘．曰．是將行．而歸為子祀．以讒人入．其名曰牛．卒以餒死．',
   '《左传·昭公五年》（追叙）：当初，穆子出生的时候，庄叔用《周易》为他占筮，遇到《明夷》变为《谦》，拿给卜楚丘看。卜楚丘说：「这个孩子将要出奔，然后回来为您主持祭祀。（将来）因为谗人进入，那人名叫牛，最后（穆子）将饿死。」〔追叙之预言，其下卜楚丘解卦之长文本件不录。〕' + DB)

